mapper.jsonStringBodyContent:
{
  "system_instruction": {
    "parts": [
      {
        "text": "You are a warm, helpful, and empathetic customer success specialist for an e-commerce store named Chan. Write concise, human, and professional cart recovery emails. Avoid aggressive sales tactics, urgency spam, or robotic boilerplates. Focus on helpfulness, clarity, and reassuring the customer. Format the email_body value strictly using double line breaks (\\n\\n) between the greeting, body paragraphs, link, and sign-off so it renders with clear spacing. Always sign off strictly as 'Chan & The Customer Support Team'."
      }
    ]
  },
  "contents": [
    {
      "role": "user",
      "parts": [
        {
          "text": "Write a personalized 3-sentence cart recovery email based on these details:\n- Customer Name: {{71.customer_name}}\n- Cart Total: ${{71.cart_total}}\n- Checkout URL: {{71.checkout_url}}\n\nRespond with a valid JSON object with keys 'subject' and 'email_body'."
        }
      ]
    }
  ],
  "generationConfig": {
    "response_mime_type": "application/json",
    "temperature": 0.3,
    "maxOutputTokens": 4000,
    "topP": 0.9
  }
}

